describe('conversation list protocol message types', () => {
  it('exports list_sessions and session_list frames with wire-safe summary dates', () => {
    const request: ListSessionsMessage = {
      type: 'list_sessions',
      limit: 25,
      before: {sessionId: 'older', updatedAt: '2026-10-01T12:00:00.000Z'},
    };
    const summary: SessionSummaryFrame = {
      sessionId: 'newer',
      createdAt: '2026-10-02T12:00:00.000Z',
      updatedAt: '2026-10-03T12:00:00.000Z',
      entryCount: 4,
    };
    const response: SessionListMessage = {type: 'session_list', sessions: [summary]};
    const incoming: IncomingMessage = request;
    const outgoing: OutgoingMessage = response;

    const fixture = fileURLToPath(import.meta.url);
    const program = ts.createProgram([fixture], {
      module: ts.ModuleKind.NodeNext,
      moduleResolution: ts.ModuleResolutionKind.NodeNext,
      noEmit: true,
      skipLibCheck: true,
      target: ts.ScriptTarget.ES2022,
      types: ['jest', 'node'],
    });
    const diagnostics = ts
      .getPreEmitDiagnostics(program)
      .filter(diagnostic => diagnostic.file?.fileName === fixture)
      .map(diagnostic => ts.flattenDiagnosticMessageText(diagnostic.messageText, '\n'));

    expect(diagnostics).toEqual([]);
    expect({incoming, outgoing}).toEqual({incoming: request, outgoing: response});
  });
});
