  it('accepts and sanitises valid list_sessions frames while rejecting invalid paging fields', () => {
    const before = {sessionId: 'older', updatedAt: '2026-10-01T12:00:00.000Z'};

    const invalid = [
      ['limit', {type: 'list_sessions', limit: -1}],
      ['limit', {type: 'list_sessions', limit: 1.5}],
      ['before.sessionId', {type: 'list_sessions', before: {sessionId: '', updatedAt: before.updatedAt}}],
      ['before.sessionId', {type: 'list_sessions', before: {sessionId: 'a'.repeat(129), updatedAt: before.updatedAt}}],
      ['before.updatedAt', {type: 'list_sessions', before: {sessionId: 'older', updatedAt: 'not-a-date'}}],
    ] as const;

    expect({
      bare: validateMessage({type: 'list_sessions'}),
      paged: validateMessage({type: 'list_sessions', limit: 0, before, userId: 'another-user'}),
      invalid: invalid.map(([field, value]) => ({field, result: validateMessage(value)})),
    }).toEqual({
      bare: {valid: true, data: {type: 'list_sessions', limit: undefined, before: undefined}},
      paged: {valid: true, data: {type: 'list_sessions', limit: 0, before}},
